mapper.select:
SELECT COUNT(*)
FROM repository
WHERE memberId = #{memberId} AND `name` = #{repoName}

mapper.update:
UPDATE draft
SET title = #{title},
    body = #{body},
    checksum = #{checksum},
    repositoryId = #{repositoryId}
WHERE id = #{id}

mapper.delete:
DELETE FROM draft
WHERE id = #{id}
  AND memberId = #{memberId}
